using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class PGroupInvariantsDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Webb =
        LibraryNoteRef.Create("D5/L/FiniteGroups/webb2016pgroups");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Nilpotent augmentation connects modular group actions to invariant vectors without dimension bounds.",
        H("Modular p-Group Invariants and Normal Subgroups"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("nilpotent-ideal-nonzero-annihilator"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupInvariants.exists_nonzero_killed_by_ideal"),
                H("The last nonzero ideal-power action"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Webb),
                Blocks(
                    Paragraph(Text("Let A be a possibly noncommutative semiring, M any A-module with an additive commutative monoid structure, and I a nilpotent two-sided ideal. Given x not equal to zero in M, there is y not equal to zero annihilated by every element of I. The semiring and module live in independent universes. The module need not be cyclic or finitely generated; the constructed vector lies in the cyclic submodule generated by x.")),
                    Paragraph(Text("Choose the least n for which every a in I raised to n satisfies a acting on x equals zero. Nilpotence supplies such n. Since one belongs to I raised to zero and fixes x, n is positive, so write n as m plus one. Minimality supplies a in I raised to m with y equal to a acting on x nonzero. For b in I, the product b times a belongs to I times I raised to m, which is I raised to m plus one. Associativity of the module action therefore gives b acting on y equals zero. The multiplication order is essential when A is noncommutative.")),
                    Paragraph(Text("This classical least-power argument is implemented as a helper actually consumed by the invariant-vector theorem below. Webb's existing Library note attests the augmentation-nilpotence input to that application, not a verbatim semiring-module statement of this helper. Repo-derived provenance records the present derivation and its acknowledged input; it is not a claim of historical novelty."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("modular-p-group-nonzero-invariant"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupInvariants.exists_nonzero_mem_invariants_of_isPGroup"),
                H("A nonzero invariant over arbitrary commutative coefficients"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Webb),
                Blocks(
                    Paragraph(Text("Let p be prime, R any commutative ring of characteristic p, P any finite p-group, and sigma a representation of P on any R-module V. A supplied nonzero vector in V yields a nonzero vector in sigma.invariants. R, P and V have independent universes. R need not be a field or finite, V has no dimension or finite-generation hypothesis, and P need not be abelian.")),
                    Paragraph(Text("Use the actual kernel I of the augmentation algebra homomorphism sending every group basis element of R[P] to one. PGroupAugmentation.augmentation_ideal_pow_card gives I raised to the cardinality of P equals zero. Regard V as sigma.asModule over R[P] and apply exists_nonzero_killed_by_ideal. For every g in P, the element of R[P] corresponding to g minus one lies in I. Representation.asModuleEquiv_map_smul and Representation.asAlgebraHom_of transport its annihilation to sigma(g)(y) minus y equals zero. Thus the nonzero image of y is fixed by every g.")),
                    Paragraph(Text("The existing NikolovSegal.PartIISL2RootSylow.pSubgroup_fixed_vector and NikolovSegal.PartIISL3UnipotentSylow.pSubgroup_fixed_vector prove the finite-field F squared and F cubed matrix-action cases by Mathlib's finite-set orbit congruence and second-fixed-point theorem. Those arguments require a finite acted-on set. This proof instead uses nilpotence on a module and retains arbitrary dimension and arbitrary commutative characteristic-p coefficients. This comparison is bounded to these named sources and makes no exhaustive library-absence claim.")),
                    Paragraph(Text("The mechanism is classical modular representation theory. Webb's Library note supports the reused augmentation nilpotence and quotient-kernel method. The exact ring-coefficient statement here is the present source derivation, not a claim that the note quotes this full telescope verbatim. This theorem is actually consumed by the normal-subgroup result below."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("normal-p-subgroup-irreducible-trivial"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupInvariants.isTrivial_restrict_normal_p_subgroup"),
                H("Normal p-subgroups act trivially in irreducible characteristic-p representations"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Webb),
                Blocks(
                    Paragraph(Text("Let k be any field of prime characteristic p, G any group, and rho an irreducible k-representation of G on any k-module V. If P is a finite normal p-subgroup of G, the restriction of rho to P is trivial: every element of P acts as the identity linear map on all of V. The field, ambient group and module have independent universes. There is no finiteness hypothesis on G, no algebraic-closure hypothesis on k and no dimension hypothesis on V.")),
                    Paragraph(Text("The existing FiniteCharacterAlgebra.Representation.IsIrreducible.nontrivial supplies a nonzero vector. The preceding theorem applied to rho restricted to P produces a nonzero P-invariant. Build W as the actual Subrepresentation of rho whose underlying submodule is the invariants of that restriction. Representation.le_comap_invariants supplies stability under every element of G using normality of P. The produced vector makes W nonzero; irreducibility makes W equal to top. Hence every vector is fixed by every element of P, which is precisely Representation.IsTrivial for the restricted representation.")),
                    Paragraph(Text("Normality is used for stability of the entire invariant submodule under the ambient action; it is not needed for the preceding fixed-vector theorem. This is the classical irreducibility consequence of the nilpotent-action mechanism. The Webb acknowledgement concerns the augmentation input to the derivation, and no exact locator or novelty claim for this full arbitrary-dimensional consumer is asserted."))),
                DescribeRole.Theorem))));
}
